# final06: правки геймплея прототипа, уровень 1-4 (раньше — часть rep_30_gameplay.py) (текстовые замены, как в rep_10/rep_20; не нашлась строка — сборка останавливается).
# ---- 1-4 «Леший водит»: ролик «Пелагею увели» — ёлки кружат Пелагею хороводом и вихрем уносят в кольцо ----
# Ролик не переписывается: его определение оборачивается в FIN.k14Kid (late_99b_kidnap14.js), который ставит хоровод, вихрь через
# изгородь и приземление в кольце; ёлки кольца, изгородь, тень Лешего и герои передаются из build14.
rep("play({dur:25.5,fov:44,camK:3.2,","play(FIN.k14Kid({dur:25.5,fov:44,camK:3.2,")
rep("banner('Пелагею увели!','#e7c3ff',2.6,'из кольца она глядит — и луч её держит ёлки на Прошкиной тропе');}});}",
    "banner('Пелагею увели!','#e7c3ff',2.6,'из кольца она глядит — и луч её держит ёлки на Прошкиной тропе');}},{ring,RC,RR,hedge,hedgeFirs,tun,shade,hats,eyes,pe,pr,yo}));}")
# ---- 1-4: ролик «Шапки из мха» — ручная постановка (late_99zx_k14_kino.js, FIN.k14Hats): шапки и пень передаются из build14 ----
rep("play({dur:12,fov:48,shots:[shot(0,[3.2,2.4,2.8],","play(FIN.k14Hats({dur:12,fov:48,shots:[shot(0,[3.2,2.4,2.8],")
rep("banner('Луч взгляда','#fff6c8',2.6,'ёлки в луче стоят на месте — хоть свет от героя, что ты оставил');}});}",
    "banner('Луч взгляда','#fff6c8',2.6,'ёлки в луче стоят на месте — хоть свет от героя, что ты оставил');}},{hats}));}")
